import math

N = 456

def count_pairs(a, b):
    """Calculates C(a, b) = binom(a, 2) + binom(b, 2)"""
    if a < 2:
        binom_a = 0
    else:
        binom_a = a * (a - 1) // 2

    if b < 2:
        binom_b = 0
    else:
        binom_b = b * (b - 1) // 2

    return binom_a + binom_b

# Test unbalanced case: {1, 455}
a1, b1 = 1, N - 1
c1 = count_pairs(a1, b1)

# Test slightly more balanced case: {2, 454}
a2, b2 = 2, N - 2
c2 = count_pairs(a2, b2)

# Test perfectly balanced case (minimum): {228, 228}
a3, b3 = N // 2, N // 2
c3 = count_pairs(a3, b3)

print(f"C(1, 455): {c1}")
print(f"C(2, 454): {c2}")
print(f"C(228, 228): {c3}")
